package au.monster.tracker;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.net.Uri;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.widget.*;
import android.view.*;
import java.io.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Entirely local profit/GST reports with SAF CSV/PDF export. */
public final class ReportsActivity extends Activity {
    private Uri pendingExport;private long unknownRefundFees;private Store store;private FinanceStore finance;private Finance.Result result;private CatalogStore.View catalogue;private LinearLayout body;private TextView status;private Finance.Summary summary;private String periodKind="month",exportKind="csv";private LocalDate date=LocalDate.now(Ledger.PERTH);private boolean busy,dead;private final ExecutorService io=Executors.newSingleThreadExecutor();
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle b){super.onCreate(b);store=new Store(this);finance=new FinanceStore(store);if(b!=null){periodKind=b.getString("periodKind","month");date=LocalDate.parse(b.getString("date",date.toString()));exportKind=b.getString("exportKind","csv");String pending=b.getString("pendingExport");if(pending!=null)pendingExport=Uri.parse(pending);}load();}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("periodKind",periodKind);b.putString("date",date.toString());b.putString("exportKind",exportKind);if(pendingExport!=null)b.putString("pendingExport",pendingExport.toString());}
    @Override protected void onDestroy(){dead=true;io.execute(store::close);io.shutdown();super.onDestroy();}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(0xfff0f5eb);t.setTextSize(size);t.setPadding(0,dp(8),0,dp(8));return t;}
    private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setMinHeight(dp(56));b.setOnClickListener(v->{if(!busy)action.run();});return b;}
    private void shell(String title){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff101410);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(16),insets.getSystemWindowInsetTop()+dp(8),dp(16),insets.getSystemWindowInsetBottom()+dp(8));return insets;});setContentView(root);root.requestApplyInsets();root.addView(text(title,24));status=text("Offline · AUD · FIFO inventory costing",14);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
    private <T> void job(Callable<T> work,java.util.function.Consumer<T> done){if(busy)return;busy=true;status.setText("Working locally…");io.execute(()->{try{T value=work.call();runOnUiThread(()->{if(dead)return;busy=false;done.accept(value);});}catch(Throwable e){runOnUiThread(()->{if(dead)return;busy=false;status.setText("No changes saved.");new AlertDialog.Builder(this).setTitle("Could not complete").setMessage(e.getMessage()).setPositiveButton("OK",null).show();});}});}
    private void load(){shell("Profit & Australian GST");job(()->{catalogue=new CatalogStore(store).view();unknownRefundFees=new RefundStore(store).view().state().unknownFees();return finance.result();},r->{result=r;show();if(pendingExport!=null){Uri uri=pendingExport;pendingExport=null;onActivityResult(81,RESULT_OK,new Intent().setData(uri));}});}
    private void show(){shell("Profit & Australian GST");String[] kinds={"day","week","month","quarter","year","financial_year","all"},labels={"Daily","Weekly (Mon–Sun)","Monthly","Quarterly","Calendar year","Australian financial year","All history"};Spinner periods=new Spinner(this);periods.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));for(int i=0;i<kinds.length;i++)if(kinds[i].equals(periodKind))periods.setSelection(i);body.addView(periods);LinearLayout values=new LinearLayout(this);values.setOrientation(1);body.addView(button("Report date: "+date,()->new DatePickerDialog(this,(v,y,m,d)->{date=LocalDate.of(y,m+1,d);show();},date.getYear(),date.getMonthValue()-1,date.getDayOfMonth()).show()));body.addView(values);periods.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View v,int position,long id){periodKind=kinds[position];draw(values);}});draw(values);body.addView(button("GST registration & product tax settings",this::taxSettings));body.addView(button("Export selected report CSV",()->export("csv")));body.addView(button("Export selected report PDF",()->export("pdf")));body.addView(button("Back to tracker",this::finish));}
    private String totals(){return "Revenue (gross): "+Ledger.money(summary.revenue())+"\nCash / card: "+Ledger.money(summary.cash())+" / "+Ledger.money(summary.card())+"\nOutput GST: "+Ledger.money(summary.outputGst())+"\nCOGS (FIFO): "+Ledger.money(summary.cogs())+"\nGross profit: "+Ledger.money(summary.grossProfit())+"\nRecorded card fees: "+Ledger.money(summary.fees())+"\nOperating expenses (net of recorded GST credits): "+Ledger.money(summary.expenses())+"\nMissing/damaged/lost & valuation corrections: "+Ledger.money(summary.losses())+"\nEstimated net profit: "+Ledger.money(summary.netProfit())+"\nStock purchases (gross): "+Ledger.money(summary.purchases())+"\nRecorded input GST credits: "+Ledger.money(summary.inputGst())+"\nEstimated GST difference: "+Ledger.money(summary.outputGst()-summary.inputGst())+"\nCurrent inventory value (all history): "+Ledger.money(summary.inventoryValue());}
    private void draw(LinearLayout values){values.removeAllViews();var period=Finance.period(periodKind,date);summary=Finance.summarize(result,period);values.addView(text(period.label(),18));values.addView(text(totals(),20));values.addView(text("Gross profit by flavour (before shared fees/expenses)",19));for(var entry:summary.flavourProfit().entrySet()){String name=entry.getKey();for(var p:catalogue.products())if(p.id().equals(entry.getKey()))name=p.name();values.addView(text(name+": "+Ledger.money(entry.getValue()),17));}values.addView(text(notes(),14));}
    private String notes(){return "GST registration defaults OFF. Historical prices, fees and GST snapshots are preserved; changing settings only affects future entries. FIFO costs follow recorded stock movement order, not backdated sale dates. Undo reverses original costs at the correction date; a consumed-restock reversal may have an explicit inventory valuation adjustment.\n\n"+summary.unknownDateRows()+" rows have unknown historical dates. They are included only in All history; no dates are invented. Purchase input credits are based on confirmed received stock and actual receipt GST. These are bookkeeping estimates, not a BAS or tax return; unreceived invoice costs, income tax and unrecorded expenses are excluded. Refund rows use verified/recorded status dates. Original processing fees remain; returned goods restore their original FIFO cost only after explicit receipt. Unknown additional refund fees: "+unknownRefundFees+" (excluded until verified). Cash/manual refunds work offline; Stripe refunds/status require the original authenticated live backend. Corrections alone are not proof of payment refunds.";}
    private void taxSettings(){shell("GST settings — future entries");Map<String,Object> settings=finance.settings();var gst=Purchases.map(settings.get("gst"));CheckBox registered=new CheckBox(this);registered.setText("I am registered for Australian GST");registered.setTextColor(0xfff0f5eb);registered.setMinHeight(dp(56));registered.setChecked(FinanceBackup.bool(gst,"registered"));body.addView(registered);CheckBox credits=new CheckBox(this);credits.setText("Claim actual GST shown on eligible recorded operating expenses");credits.setTextColor(0xfff0f5eb);credits.setChecked(FinanceBackup.bool(gst,"expenseCredits"));credits.setMinHeight(dp(56));body.addView(credits);body.addView(text("No registration is assumed. Configure only the treatment appropriate to your business. Sale prices are GST-inclusive when registered; GST-free and input-taxed products have no output GST. Input-taxed inventory does not receive an input credit.",15));Map<String,Spinner> pickers=new LinkedHashMap<>();String[] modes={"taxable","gst_free","input_taxed"};for(var p:catalogue.products()){body.addView(text(p.name(),16));Spinner picker=new Spinner(this);picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Taxable (10% inclusive)","GST-free","Input-taxed"}));String current=settings.get("product:"+p.id())==null?"taxable":Purchases.str(Purchases.map(settings.get("product:"+p.id())),"treatment");for(int i=0;i<modes.length;i++)if(modes[i].equals(current))picker.setSelection(i);body.addView(picker);pickers.put(p.id(),picker);}body.addView(button("Save future GST settings",()->{Map<String,String> choices=new LinkedHashMap<>();for(var e:pickers.entrySet())choices.put(e.getKey(),modes[e.getValue().getSelectedItemPosition()]);boolean r=registered.isChecked(),c=credits.isChecked();new AlertDialog.Builder(this).setTitle("Change future tax treatment?").setMessage("Existing records and GST snapshots will remain unchanged. This settings change is audited.").setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->job(()->{finance.saveSettings(r,c,choices);return true;},ok->load())).show();}));body.addView(button("Back to reports",this::show));}
    private void export(String kind){exportKind=kind;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(kind.equals("pdf")?"application/pdf":"text/csv");intent.putExtra(Intent.EXTRA_TITLE,"monster-report-"+periodKind+"-"+date+"."+kind);try{startActivityForResult(intent,81);}catch(ActivityNotFoundException e){new AlertDialog.Builder(this).setMessage("No file picker available. No file was written.").setPositiveButton("OK",null).show();}}
    @Override protected void onActivityResult(int request,int status,Intent data){super.onActivityResult(request,status,data);if(request!=81||status!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(busy||summary==null){pendingExport=uri;return;}String kind=exportKind;Finance.Summary selected=summary;String text=Finance.period(periodKind,date).label()+"\n\n"+totals()+"\n\nProfit by flavour:\n";for(var e:selected.flavourProfit().entrySet()){String name=e.getKey();for(var p:catalogue.products())if(p.id().equals(e.getKey()))name=p.name();text+=name+": "+Ledger.money(e.getValue())+"\n";}text+="\n"+notes();String report=text;job(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open export destination.");if(kind.equals("csv"))out.write(Finance.csv(selected).getBytes(java.nio.charset.StandardCharsets.UTF_8));else writePdf(out,report);out.flush();}return true;},ok->this.status.setText("Report exported. Data remains on this phone."));}
    static void writePdf(OutputStream out,String report)throws IOException{PdfDocument document=new PdfDocument();try{Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.BLACK);paint.setTextSize(12);int pageNumber=0,y=0;PdfDocument.Page page=null;for(String paragraph:report.split("\n",-1)){List<String> lines=new ArrayList<>();StringBuilder current=new StringBuilder();for(String word:paragraph.split(" ")){String candidate=current.length()==0?word:current+" "+word;if(paint.measureText(candidate)>515&&current.length()>0){lines.add(current.toString());current.setLength(0);current.append(word);}else {current.setLength(0);current.append(candidate);}}lines.add(current.toString());for(String line:lines){if(page==null||y>785){if(page!=null)document.finishPage(page);page=document.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNumber).create());y=40;}page.getCanvas().drawText(line,40,y,paint);y+=18;}}if(page!=null)document.finishPage(page);document.writeTo(out);}finally{document.close();}}
}
